Jest.describe("moment duration", () => {
  Jest.test("get duration", () => Jest.ExpectJs.toBeTruthy(Jest.ExpectJs.expect(Moment.default.duration(2, "days"))));
  Jest.test("get duration millis", () => Jest.ExpectJs.toBeTruthy(Jest.ExpectJs.expect(Moment.default.duration(2.0))));
  Jest.test("get duration format", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration("P2D").toJSON()), "P2D"));
  Jest.test("#milliseconds", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "milliseconds").milliseconds()), 2));
  Jest.test("#seconds", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "seconds").seconds()), 2));
  Jest.test("#asSeconds", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "seconds").asSeconds()), 2));
  Jest.test("#minutes", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "minutes").minutes()), 2));
  Jest.test("#asMinutes", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "minutes").asMinutes()), 2));
  Jest.test("#hours", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "hours").hours()), 2));
  Jest.test("#asHours", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "hours").asHours()), 2));
  Jest.test("#days", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "days").days()), 2));
  Jest.test("#asDays", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "days").asDays()), 2));
  Jest.test("#weeks", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "weeks").weeks()), 2));
  Jest.test("#asWeeks", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "weeks").asWeeks()), 2));
  Jest.test("#months", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "months").months()), 2));
  Jest.test("#asMonths", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "months").asMonths()), 2));
  Jest.test("#years", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "years").years()), 2));
  Jest.test("#asYears", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "years").asYears()), 2));
  Jest.test("#as", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "days").as("days")), 2));
  Jest.test("#toJSON", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "days").toJSON()), "P2D"));
  Jest.test("#toISOString", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "days").toJSON()), "P2D"));
  Jest.test("#humanize", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(Moment.default.duration(2, "days").humanize()), "2 days"));
});

Jest.describe("moment diff", () => {
  Jest.test("should return correct difference of moments in days", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(MomentRe_Helpers.moment(undefined, "2017-01-02").diff(MomentRe_Helpers.moment(undefined, "2017-01-01"), "days")), 1));
  Jest.test("should return correct difference of moments in hours", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(MomentRe_Helpers.moment(undefined, "2017-01-01 02:00:00.000").diff(MomentRe_Helpers.moment(undefined, "2017-01-01 00:00:00.000"), "hours")), 2));
  Jest.test("should be able to handle negative difference of moments", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(MomentRe_Helpers.moment(undefined, "2017-01-01 00:00:00.000").diff(MomentRe_Helpers.moment(undefined, "2017-01-01 02:00:00.000"), "hours")), -2));
  Jest.test("should return correct difference of moments in hours", () => Jest.ExpectJs.toBe(Jest.ExpectJs.expect(MomentRe_Helpers.moment(undefined, "2017-01-01 00:25:05.000").diff(MomentRe_Helpers.moment(undefined, "2017-01-01 00:00:00.000"), "minutes")), 25));
});

